function GenerationStudio({user}:{user:SessionUser}) {
 const [kind,setKind]=useState("lesson_notes"),[curricula,setCurricula]=useState<Curriculum[]>([]),[curriculum,setCurriculum]=useState("");
 const [topics,setTopics]=useState<Topic[]>([]),[topic,setTopic]=useState(""),[weeks,setWeeks]=useState(2),[periods,setPeriods]=useState(5),[termStart,setTermStart]=useState(new Date().toISOString().slice(0,10)),[term,setTerm]=useState("Term 1");
 const [duration,setDuration]=useState(40),[marks,setMarks]=useState(20),[questions,setQuestions]=useState(10),[busy,setBusy]=useState(false),[error,setError]=useState("");
 const [job,setJob]=useState<Job & {document_id?:string}|null>(null);
 useEffect(()=>{api<Page<Curriculum>>("/api/v1/curricula?page_size=100").then(r=>setCurricula(readPage(r))).catch(e=>setError(toMessage(e)));},[]);
 useEffect(()=>{setTopic("");setTopics([]);if(curriculum)api<Page<Topic>>("/api/v1/curricula/"+curriculum+"/topics?page_size=100").then(r=>setTopics(readPage(r))).catch(e=>setError(toMessage(e)));},[curriculum]);
 useEffect(()=>{if(!job||["failed","cancelled","succeeded"].includes(job.status))return;const timer=setInterval(()=>{api<Job>("/api/v1/generations/"+job.id).then(setJob).catch(e=>setError(toMessage(e)));},2000);return()=>clearInterval(timer);},[job]);
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const selected=topics.find(t=>t.id===topic);if(!selected?.subject_id||!selected.level_id)throw new Error("Select a curriculum topic.");const payload:Generate={document_type:kind,curriculum_id:curriculum,subject_id:selected.subject_id,level_id:selected.level_id,topic_ids:[topic],options:{depth:"comprehensive",duration_minutes:duration,total_marks:marks,question_count:questions,weeks,periods_per_week:periods,period_minutes:40,term,academic_year:termStart.slice(0,4),calendar:{starts_on:termStart,ends_on:new Date(new Date(termStart).getTime()+(weeks*7-1)*86400000).toISOString().slice(0,10)}},resource_filters:{}};setJob(await api<Job>("/api/v1/generations",{method:"POST",body:JSON.stringify(payload)}));}catch(e){setError(toMessage(e));}finally{setBusy(false);}}
 return <><Header title="Generation studio" sub="Choose your curriculum and topic. Only approved learning outcomes and permitted sources are used."/><div className="soma-grid-4 mb-8">{documentTypes.map(item=><button key={item.id} onClick={()=>setKind(item.id)} aria-pressed={kind===item.id} className={"soma-card text-left "+(kind===item.id?"!border-teal-500 !bg-teal-50":"")}><p className="font-extrabold">{item.title}</p><p className="soma-muted mt-2">{item.description}</p></button>)}</div><form onSubmit={submit} className="soma-card grid gap-5 max-w-3xl"><label className="soma-label">Curriculum<select aria-label="Curriculum" required className="soma-input" value={curriculum} onChange={e=>setCurriculum(e.target.value)}><option value="">Select curriculum</option>{curricula.map(c=><option key={c.id} value={c.id}>{c.country} · {c.name} · {c.version}</option>)}</select></label><label className="soma-label">Class, subject and topic<select aria-label="Class, subject and topic" required className="soma-input" value={topic} onChange={e=>setTopic(e.target.value)}><option value="">Select topic</option>{topics.map(t=><option key={t.id} value={t.id}>{t.grade} · {t.subject} · {t.title||t.name}</option>)}</select></label>{kind==="scheme_of_work"&&<div className="soma-grid-2"><label className="soma-label">Term<input className="soma-input" value={term} onChange={e=>setTerm(e.target.value)}/></label><label className="soma-label">First teaching day<input type="date" required className="soma-input" value={termStart} onChange={e=>setTermStart(e.target.value)}/></label><label className="soma-label">Teaching weeks<input className="soma-input" type="number" min={1} max={53} value={weeks} onChange={e=>setWeeks(+e.target.value)}/></label><label className="soma-label">Periods per week<input className="soma-input" type="number" min={1} max={50} value={periods} onChange={e=>setPeriods(+e.target.value)}/></label></div>}<label className="soma-label">Duration in minutes<input className="soma-input" type="number" min={5} max={480} value={duration} onChange={e=>setDuration(+e.target.value)}/></label>{["exam","test","quiz","assignment"].includes(kind)&&<div className="soma-grid-2"><label className="soma-label">Total marks<input className="soma-input" type="number" min={1} max={500} value={marks} onChange={e=>setMarks(+e.target.value)}/></label><label className="soma-label">Question count<input className="soma-input" type="number" min={1} max={200} value={questions} onChange={e=>setQuestions(+e.target.value)}/></label></div>}<button disabled={busy||!isEditor(user.role)} className="soma-button">Generate draft</button><ErrorNotice message={error}/>{job&&<Notice>Generation: {job.status} · {job.progress}% {job.error}<br/>{job.status==="succeeded"&&<a href={job.document_id?"/editor?document="+job.document_id:"/editor?job="+job.id}>Open draft for editing and review →</a>}</Notice>}</form></>;
}
function Documents(){const [documents,setDocuments]=useState<Array<{id:string;title:string;document_type:string;generation_job_id?:string;review_state?:string}>>([]);const [busy,setBusy]=useState(true);const [error,setError]=useState("");
 useEffect(()=>{api<Page<{id:string;title:string;document_type:string;generation_job_id?:string}>>("/api/v1/documents").then(r=>setDocuments(readPage(r))).catch(e=>setError(toMessage(e))).finally(()=>setBusy(false));},[]);
 return <><Header title="Generated documents" sub="Open your school’s saved documents and continue reviewing or editing." extra={<a href="/generate" className="soma-button">✦ Create document</a>}/><div className="soma-card">{busy?<Spinner/>:error?<ErrorNotice message={error}/>:documents.length?documents.map(d=><a className="mb-3 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-200 p-5 hover:bg-slate-50" href={"/editor?document="+encodeURIComponent(d.id)} key={d.id}><div><p className="font-bold">{d.title}</p><p className="soma-muted">{d.document_type}</p></div><Tag>{d.review_state||"See versions"}</Tag></a>):<Notice>No generated documents found. Start with the generation studio.</Notice>}</div></>;
}
function renderBlock(block:Block,editable:boolean,onChange?:(text:string,field?:"text"|"latex"|"rows"|"caption")=>void){
 if(block.type==="equation")return <div className="grid gap-3"><MathEquation latex={block.latex||block.text||""}/>{editable&&<label className="soma-label soma-no-print">Correct LaTeX source<textarea className="soma-input font-mono" rows={2} aria-label="Edit equation LaTeX" value={block.latex||""} onChange={e=>onChange?.(e.target.value,"latex")}/></label>}</div>;
 if(block.type==="table")return <div className="overflow-x-auto"><table className="soma-table"><tbody>{(block.rows||[]).map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{editable?<input className="soma-input" aria-label={"Table row "+(i+1)+" column "+(j+1)} value={cell} onChange={e=>{const rows=(block.rows||[]).map(r=>[...r]);rows[i][j]=e.target.value;onChange?.(JSON.stringify(rows),"rows");}}/>:cell}</td>)}</tr>)}</tbody></table></div>;
 if(["figure","diagram","map","chart","image"].includes(block.type))return <div className="rounded-xl border border-dashed border-amber-200 bg-amber-50 p-4 text-sm text-amber-900"><p className="font-bold">Visual asset requires verified license and resolved storage URL</p><p>Asset: {block.asset_ref||"Not linked"}</p>{editable?<label className="soma-label mt-3">Illustration caption<textarea className="soma-input" value={block.caption||""} onChange={e=>onChange?.(e.target.value,"caption")}/></label>:<p>{block.caption||"No caption provided"}</p>}</div>;
 const text=block.text||"";
 if(editable)return <textarea aria-label={"Edit "+block.type} rows={Math.max(2,Math.min(12,Math.ceil(text.length/95)))} value={text} onChange={e=>onChange?.(e.target.value)} />;
 if(block.type==="heading")return <h3 className="text-xl font-extrabold">{text}</h3>;
 if(block.type==="list")return <ul className="list-inside list-disc"><li>{text}</li></ul>;
 return <p className="whitespace-pre-wrap">{text}</p>;
}
type VersionRow = {id:string;version:number;created_at:string};
function Editor({user}:{user:SessionUser}){
 const [draft,setDraft]=useState<Draft|null>(null);const [jobId,setJobId]=useState("");const [documentId,setDocumentId]=useState("");const [currentVersion,setCurrentVersion]=useState(0);const [versions,setVersions]=useState<VersionRow[]>([]);
 const [busy,setBusy]=useState(false);const [dirty,setDirty]=useState(false);const [error,setError]=useState("");const [status,setStatus]=useState("");
 const load=useCallback(async(id:string)=>{setBusy(true);setError("");setStatus("");setDocumentId("");try{const value=await api<unknown>("/api/v1/generations/"+encodeURIComponent(id)+"/draft");const envelope=value as {document_id?:string};if(envelope.document_id){await loadDocument(envelope.document_id);}else{setDraft(normalizeDraft(value));setDirty(false);}}catch(e){setError(toMessage(e));}finally{setBusy(false);}},[]);
 const loadDocument=useCallback(async(id:string,version?:string)=>{setBusy(true);setError("");setStatus("");try{
  const list=readPage(await api<Page<VersionRow>>("/api/v1/documents/"+encodeURIComponent(id)+"/versions"));if(!list.length)throw new Error("Document has no saved versions.");
  const selected=list.find(row=>row.id===version)||list[0];
  const value=await api<unknown>("/api/v1/documents/"+encodeURIComponent(id)+"/versions/"+encodeURIComponent(selected.id));
  setDraft(normalizeDraft(value));setCurrentVersion(selected.version);setVersions(list);setDocumentId(id);setDirty(false);
 }catch(e){setError(toMessage(e));}finally{setBusy(false);}},[]);
 useEffect(()=>{const args=new URLSearchParams(window.location.search);const doc=args.get("document"),job=args.get("job");if(doc){void loadDocument(doc);}else if(job){setJobId(job);void load(job);}},[load,loadDocument]);
 function edit(section:number,block:number,value:string,field:"text"|"latex"|"rows"|"caption"="text"){if(!draft)return;const update=field==="rows"?{rows:JSON.parse(value) as string[][]}:{[field]:value};setDraft(prev=>prev&&({...prev,body:{...prev.body,sections:prev.body.sections.map((s,i)=>i!==section?s:{...s,blocks:s.blocks.map((b,j)=>j!==block?b:{...b,...update})})}}));setDirty(true);}
 async function save(){if(!draft||!documentId)return;setBusy(true);setError("");try{
  const result=await api<{id:string;version:number;review_state:string}>("/api/v1/documents/"+encodeURIComponent(documentId)+"/versions",{method:"POST",body:JSON.stringify({expected_version:currentVersion,body:draft.body})});
  setCurrentVersion(result.version);setDraft({...draft,id:result.id,review_state:"draft"});setDirty(false);await loadDocument(documentId,result.id);setStatus("Saved as new version "+result.version+". This version requires a fresh educator approval.");
 }catch(e){setError(toMessage(e));}finally{setBusy(false);}}
 function print(){if(dirty)return setError("Save your changes and obtain review approval before printing.");if(draft?.review_state!=="approved")return setError("Printing is restricted to educator-approved versions. Use the publishing center for a final export.");window.print();}
 return <><Header title="Document editor" sub="Edit structured blocks, inspect source IDs and save revisions without overwriting approved documents." extra={<Tag>{dirty?"Unsaved changes":documentId?"Saved revision":"Generation draft"}</Tag>}/><form onSubmit={e=>{e.preventDefault();void load(jobId);}} className="soma-card soma-no-print mb-6 flex flex-wrap gap-3"><input className="soma-input flex-1" value={jobId} onChange={e=>setJobId(e.target.value)} placeholder="Generation job UUID" aria-label="Generation job UUID" required/><button className="soma-button" disabled={busy}>Load generated draft</button>{draft&&<button type="button" className="soma-button secondary" onClick={print}>Approved print preview</button>}{documentId&&dirty&&isEditor(user.role)&&<button type="button" disabled={busy} className="soma-button" onClick={()=>void save()}>Save new version</button>}</form><ErrorNotice message={error}/>{status&&<Notice>{status}</Notice>}{busy?<Spinner/>:draft?<div className="soma-grid-2 lg:!grid-cols-[minmax(0,1fr)_300px]"><div className="soma-preview"><div className="mb-10 border-b-2 border-slate-800 pb-7"><p className="text-xs font-bold uppercase tracking-widest text-slate-500">SomaLoom · {draft.review_state==="approved"?"Approved version":"Draft — not for distribution"}</p><h2 className="mt-3 text-3xl font-extrabold">{draft.title}</h2><p className="soma-muted mt-2">{draft.document_type.replaceAll("_"," ")} · {draft.id}</p></div>{draft.body.sections.map((section,i)=><section key={section.id||i} className="mb-7"><h3 className="mb-3 text-xl font-extrabold">{section.title}</h3>{section.blocks.map((block,j)=><div key={block.id} className="soma-block">{renderBlock(block,isEditor(user.role),(value,field)=>edit(i,j,value,field))}{Boolean(block.citations?.length)&&<p className="mt-2 text-[11px] text-teal-700">Evidence IDs: {block.citations?.join(", ")}</p>}</div>)}</section>)}</div><aside className="soma-card self-start lg:sticky lg:top-24"><h3 className="soma-card-heading">Quality inspector</h3><p className="soma-muted mt-3">Inspect source citations, mathematics, images and assessment answers.</p><div className="mt-6 grid gap-3"><p className="text-sm"><strong>State:</strong> {draft.review_state||"Unreviewed"}</p><p className="text-sm"><strong>Evidence links:</strong> {draft.evidence_ids?.length||0}</p><p className="text-sm"><strong>Blocks:</strong> {draft.body.sections.reduce((n,s)=>n+s.blocks.length,0)}</p>{documentId&&<p className="text-sm"><strong>Version:</strong> {currentVersion}</p>}</div><hr className="soma-divider"/><Notice>{dirty?"Edited locally — save a new version before leaving.":documentId?"Version loaded from your school's document library.":"Open this saved draft from My documents to edit revisions."}</Notice>{versions.length>1&&<div className="mt-5"><h4 className="mb-3 text-sm font-bold">Version history</h4>{versions.map(v=><button key={v.id} disabled={dirty||busy} onClick={()=>void loadDocument(documentId,v.id)} className="mb-2 block w-full rounded-lg border border-slate-200 p-2 text-left text-sm">Version {v.version} {v.id===draft.id?"(open)":""}</button>)}</div>}{documentId&&canReview(user.role)&&<a href={"/review?document="+encodeURIComponent(documentId)+"&version="+encodeURIComponent(draft.id)} className="soma-button secondary mt-5 w-full">Review this version →</a>}{documentId&&draft.review_state==="approved"&&<a href={"/publish?version="+encodeURIComponent(draft.id)} className="soma-button mt-3 w-full">Publish approved version</a>}<div className="mt-5"><Pending owner="Agent 5" action="Targeted section regeneration and visual replacement"/></div></aside></div>:<div className="soma-card"><Notice>Enter a job ID or open a document from your library. This editor does not invent generated content.</Notice></div>}</>;
}
function Review({user}:{user:SessionUser}){
 const [documentId,setDocumentId]=useState("");const [versionId,setVersionId]=useState("");const [decision,setDecision]=useState("approved");const [comments,setComments]=useState("");
 const [citations,setCitations]=useState(false);const [math,setMath]=useState(false);const [license,setLicense]=useState(false);
 const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [saved,setSaved]=useState("");
 useEffect(()=>{const args=new URLSearchParams(window.location.search);setDocumentId(args.get("document")||"");setVersionId(args.get("version")||"");},[]);
 async function submit(e:FormEvent){e.preventDefault();setError("");setSaved("");setBusy(true);try{
  if(!canReview(user.role))throw new Error("Your role does not permit review decisions.");
  const payload={decision,comments,citations_checked:citations,mathematics_checked:math,licensing_checked:license};
  const result=await api<{decision:string}>("/api/v1/documents/"+encodeURIComponent(documentId)+"/versions/"+encodeURIComponent(versionId)+"/review",{method:"POST",body:JSON.stringify(payload)});
  setSaved("Version review recorded: "+result.decision+". This decision is linked to the exact version, not future edits.");
 }catch(e){setError(toMessage(e));}finally{setBusy(false);}}
 return <><Header title="Review & approval" sub="Check facts, source evidence, mathematics and licenses before signing off a version."/><div className="soma-grid-3 mb-6">{[["Evidence & citations","Check each source against the original page or URL.","◈"],["Visual integrity","Check diagrams, attribution and map legends.","▣"],["Assessment validity","Verify marks, worked answers and separate student versions.","✓"]].map(([title,desc,symbol])=><div className="soma-card" key={title}><p className="text-3xl text-teal-700">{symbol}</p><h2 className="soma-card-heading mt-4">{title}</h2><p className="soma-muted mt-3">{desc}</p></div>)}</div><form onSubmit={submit} className="soma-card grid max-w-3xl gap-5"><h2 className="soma-card-heading">Record an educator decision</h2><div className="soma-grid-2"><label className="soma-label">Document ID<input required className="soma-input" value={documentId} onChange={e=>setDocumentId(e.target.value)} /></label><label className="soma-label">Document version ID<input required className="soma-input" value={versionId} onChange={e=>setVersionId(e.target.value)}/></label></div><label className="soma-label">Decision<select className="soma-input" value={decision} onChange={e=>setDecision(e.target.value)}><option value="approved">Approve version</option><option value="rejected">Reject and return for correction</option></select></label>{decision==="approved"&&<fieldset className="grid gap-3 rounded-xl border border-slate-200 p-5"><legend className="px-2 text-xs font-extrabold">Required verification attestations</legend><label className="flex gap-3 text-sm"><input type="checkbox" checked={citations} onChange={e=>setCitations(e.target.checked)}/> Source evidence and citations verified</label><label className="flex gap-3 text-sm"><input type="checkbox" checked={math} onChange={e=>setMath(e.target.checked)}/> Mathematics and marking calculations checked</label><label className="flex gap-3 text-sm"><input type="checkbox" checked={license} onChange={e=>setLicense(e.target.checked)}/> Visual labels and reproduction rights confirmed</label></fieldset>}<label className="soma-label">Review comments<textarea className="soma-input" rows={4} minLength={8} required value={comments} onChange={e=>setComments(e.target.value)} placeholder="Describe checks performed and required corrections."/></label><button className="soma-button justify-self-start" disabled={busy||!canReview(user.role)}>Record version decision</button><ErrorNotice message={error}/>{saved&&<Notice>{saved}</Notice>}{!canReview(user.role)&&<Notice error>Your role cannot approve or reject documents.</Notice>}</form></>;
}
function Publish({user}:{user:SessionUser}){
 const [id,setId]=useState("");const [format,setFormat]=useState("pdf");const [audience,setAudience]=useState("student");const [status,setStatus]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [download,setDownload]=useState("");
 useEffect(()=>{setId(new URLSearchParams(window.location.search).get("version")||"");},[]);
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError("");setStatus("");setDownload("");try{
  const value=await api<{id:string;job_id:string;status:string;download_url:string}>("/api/v1/exports",{method:"POST",body:JSON.stringify({document_version_id:id,format,audience,asynchronous:true})});
  if(!value.download_url.startsWith("/api/v1/exports/")||!value.download_url.endsWith("/download"))throw new Error("Invalid export download reference.");
  if(value.status!=="succeeded"){
    setStatus("Preparing your reviewed document…");
    let complete=false;
    for(let attempt=0;attempt<120;attempt++){
      await new Promise(resolve=>setTimeout(resolve,1000));
      const job=await api<Job>("/api/v1/jobs/"+value.job_id);
      if(job.status==="succeeded"){complete=true;break;}
      if(["failed","cancelled"].includes(job.status))throw new Error(job.error||"Export did not complete.");
    }
    if(!complete)throw new Error("Export is still processing. Check job "+value.job_id+" before downloading.");
  }
  setStatus("Your reviewed file is ready to download.");setDownload(value.download_url);
 }catch(e){setError(toMessage(e));}finally{setBusy(false);}}
 return <><Header title="Publishing center" sub="Prepare school-branded, printable A4 publications with strictly separated audience editions."/><div className="soma-grid-2"><form className="soma-card grid gap-5" onSubmit={submit}><h2 className="soma-card-heading">Export an approved version</h2><label className="soma-label">Approved document version UUID<input className="soma-input" value={id} onChange={e=>setId(e.target.value)} required placeholder="Document version UUID"/></label><label className="soma-label">File format<select className="soma-input" value={format} onChange={e=>setFormat(e.target.value)}><option value="pdf">PDF · A4 print</option><option value="docx">DOCX · Editable Office document</option></select></label><label className="soma-label">Publication audience<select className="soma-input" value={audience} onChange={e=>setAudience(e.target.value)}><option value="student">Student version (no answers)</option>{["teacher","school_admin","reviewer"].includes(user.role)&&<option value="teacher">Teacher marking guide (restricted)</option>}</select></label><button disabled={busy} className="soma-button">{busy?"Preparing…":"Prepare export"}</button><ErrorNotice message={error}/>{status&&<Notice>{status}</Notice>}{download&&<a className="soma-button" href={download}>↓ Download authenticated {format.toUpperCase()}</a>}</form><div className="soma-card"><h2 className="soma-card-heading">Preflight checklist</h2><div className="mt-6 grid gap-4">{["Educator approval recorded for this exact version","Math equations verified and typeset","Images licensed with captions and attribution","Citations resolve to source evidence","School name and page numbers checked","Answer keys excluded from student version"].map(item=><p className="flex items-center gap-3 text-sm" key={item}><span className="text-teal-700">□</span>{item}</p>)}</div><hr className="soma-divider"/><p className="soma-muted">Publishing only succeeds if the server checks school ownership, signed-off revision and staff permissions. Files are retrieved through authenticated tenant-scoped downloads.</p></div></div></>;
}
function QuestionBank(){const [error,setError]=useState("");const [items,setItems]=useState<Array<{id:string;stem?:string;question_text?:string;marks?:number}>>([]);const [busy,setBusy]=useState(true);
 useEffect(()=>{api<Page<{id:string;stem?:string;question_text?:string;marks?:number}>>("/api/v1/question-bank").then(r=>setItems(readPage(r))).catch(e=>setError(toMessage(e))).finally(()=>setBusy(false));},[]);
 return <><Header title="Question bank" sub="Reusable, evidence-linked questions for quizzes, tests, worksheets and examinations."/><div className="soma-card">{busy?<Spinner/>:error?<ErrorNotice message={error}/>:items.length?items.map(q=><div className="border-b border-slate-100 py-4" key={q.id}><p className="font-semibold">{q.stem||q.question_text||"Untitled question"}</p><p className="soma-muted">{q.marks??"—"} marks</p></div>):<Notice>No questions available for your authorized school.</Notice>}</div></>;
}
function Schools({user}:{user:SessionUser}){const [items,setItems]=useState<School[]>([]);const [error,setError]=useState("");useEffect(()=>{api<Page<School>>("/api/v1/schools").then(r=>setItems(readPage(r))).catch(e=>setError(toMessage(e)));},[]);
 return <><Header title="School settings" sub="Your account’s schools and organization context. Membership is enforced by the backend."/><div className="soma-grid-2"><div className="soma-card"><h2 className="soma-card-heading">School memberships</h2><div className="mt-5">{items.map(s=><div className="mb-4 rounded-xl border border-slate-100 p-4" key={s.id}><p className="font-bold">{s.name}</p><p className="soma-muted">School ID: {s.id}</p></div>)}</div><ErrorNotice message={error}/></div><div className="soma-card"><h2 className="soma-card-heading">Your account</h2><p className="mt-5 font-bold">{user.name}</p><p className="soma-muted">{user.email}</p><p className="mt-4"><Tag>{user.role}</Tag></p><hr className="soma-divider"/><Pending owner="Agent 1" action="Editable school branding / logo controls"/></div></div></>;
}
export default function StudioApp({section}:{section:Section}) {
 const [user,setUser]=useState<SessionUser|null>(null);const [loading,setLoading]=useState(true);const [error,setError]=useState("");const [loggingOut,setLoggingOut]=useState(false);
 useEffect(()=>{api<SessionUser>("/api/v1/users/me").then(setUser).catch(e=>{if(toMessage(e)!=="Request failed (401)")setError(toMessage(e));}).finally(()=>setLoading(false));},[]);
 async function logout(){setLoggingOut(true);setError("");try{await api<void>("/api/v1/auth/logout",{method:"POST"});setUser(null);}catch(e){setError(toMessage(e));}finally{setLoggingOut(false);}}
 if(loading)return <main className="flex min-h-screen items-center justify-center"><Spinner/></main>;
 if(!user)return <Login onLogin={setUser}/>;
 const title=routes.find(r=>r.id===section)?.label||"Overview";
 return <div className="soma-app"><aside className="soma-sidebar" aria-label="Primary navigation"><a href="/" className="soma-logo"><span>✦</span><span>SomaLoom</span></a><p className="soma-nav-heading">Navigate</p><nav className="soma-nav" aria-label="Workspace">{routes.map((r,i)=><div key={r.id}>{i>0&&r.group!==routes[i-1].group&&<p className="soma-nav-heading">{r.group}</p>}<a href={r.id==="dashboard"?"/":"/"+r.id} className="soma-nav-link" aria-current={section===r.id?"page":undefined}><span className="soma-symbol" aria-hidden>{r.symbol}</span>{r.label}</a></div>)}</nav><div className="mt-auto rounded-xl bg-[#153a44] p-4"><p className="text-xs font-bold text-emerald-200">Your workspace</p><p className="mt-2 truncate text-sm font-bold text-white">{user.name}</p><p className="mt-1 text-xs text-slate-300">{user.role.replaceAll("_"," ")}</p></div></aside><div className="soma-main"><div className="soma-topbar" role="banner"><div><p className="text-sm font-bold">{title}</p><p className="text-xs text-slate-500">Trusted sources → teaching materials</p></div><div className="flex items-center gap-3"><span className="hidden rounded-full bg-emerald-50 px-3 py-2 text-xs font-semibold text-teal-800 sm:inline">{user.tenant_id?"School workspace":"Platform account"}</span><button onClick={logout} className="soma-button ghost" disabled={loggingOut}>{loggingOut?"Signing out…":"Sign out"}</button></div></div><main className="soma-content"><ErrorNotice message={error}/>{section==="dashboard"?<Dashboard user={user}/>:section==="library"?<Library/>:section==="statistics"?<ResourceStatistics/>:section==="upload"?<Upload/>:section==="telegram"?<Telegram/>:section==="imports"?<Imports/>:section==="processing"?<Processing/>:section==="curriculum"?<CurriculumBrowser/>:section==="evidence"?<EvidenceExplorer user={user}/>:section==="generate"?<GenerationStudio user={user}/>:section==="documents"?<Documents/>:section==="editor"?<Editor user={user}/>:section==="review"?<Review user={user}/>:section==="publish"?<Publish user={user}/>:section==="question-bank"?<QuestionBank/>:<Schools user={user}/>}</main></div></div>;
}
